mapper.select:
select b.borrow_id, b.store_id, b.borrow_no, b.member_id, b.member_no, b.member_name,
       b.level_id, b.book_id, b.isbn, b.title, b.bar_code, b.location_id,
       b.deposit_amount, b.borrow_time, b.due_time, b.return_time, b.renew_count,
       b.is_overdue, b.overdue_days, b.fine_amount, b.fine_paid, b.is_compensated,
       b.status, b.operator_by, b.create_by, b.create_time, b.update_by, b.update_time,
       b.remark
from biz_borrow b


        and b.borrow_no = #{borrowNo}


        and b.member_id = #{memberId}


        and b.member_no = #{memberNo}


        and b.book_id = #{bookId}


        and b.isbn = #{isbn}


        and b.bar_code = #{barCode}


        and b.is_overdue = #{isOverdue}


        and b.status = #{status}


        and b.borrow_time >= #{params.beginTime}


        and b.borrow_time <= #{params.endTime}


order by b.borrow_id desc

select b.borrow_id as borrowId, b.borrow_no as borrowNo, b.member_id as memberId, b.member_name as memberName, m.phone as phone, b.title as title, b.bar_code as barCode, b.due_time as dueTime, datediff(#{now}, b.due_time) as overdueDays, ifnull(bk.price, 0.00) as calcBase from biz_borrow b left join biz_book bk on bk.book_id = b.book_id left join biz_member m on m.member_id = b.member_id where b.status in (1, 3) and b.return_time is null and date(b.due_time) < date(#{now})
and b.member_id = #{memberId}
and b.status = #{status}
and datediff(#{now}, b.due_time) >= #{minOverdueDays}
order by b.due_time asc

select b.book_id as bookId, b.isbn as isbn, b.title as title, count(*) as lendCount
from biz_borrow b
where b.borrow_time >= #{from} and b.borrow_time <= #{to}
group by b.book_id, b.isbn, b.title
order by lendCount desc, b.book_id asc
limit #{limit}

select min(b.due_time)
from biz_borrow b
where b.status in (1, 3)
  and b.return_time is null

      and b.member_id = #{memberId}


      and b.book_id = #{bookId}
